-- PostgreSQL starter schema. Tenant ownership is explicit; add PostgreSQL RLS policies before production.
CREATE TABLE institutes (id BIGSERIAL PRIMARY KEY, institute_code VARCHAR(80) UNIQUE NOT NULL, name VARCHAR(200) NOT NULL, short_form VARCHAR(30) NOT NULL, required_percent NUMERIC(5,2) NOT NULL DEFAULT 75 CHECK(required_percent > 0 AND required_percent <= 100));
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, institute_id BIGINT NOT NULL REFERENCES institutes(id), user_code VARCHAR(80) NOT NULL, name VARCHAR(200) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','TEACHER','STUDENT')), pin_hash VARCHAR(255) NOT NULL, UNIQUE(institute_id,user_code));
CREATE TABLE students (id BIGSERIAL PRIMARY KEY, institute_id BIGINT NOT NULL REFERENCES institutes(id), roll_number VARCHAR(40) NOT NULL, admission_number VARCHAR(80), name VARCHAR(200) NOT NULL, UNIQUE(institute_id,roll_number));
CREATE TABLE attendance_sessions (id BIGSERIAL PRIMARY KEY, institute_id BIGINT NOT NULL REFERENCES institutes(id), session_date DATE NOT NULL, class_code VARCHAR(80) NOT NULL, subject VARCHAR(200) NOT NULL, teacher_user_id BIGINT NOT NULL REFERENCES users(id), start_time TIME NOT NULL, end_time TIME NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING');
CREATE TABLE attendance_records (id BIGSERIAL PRIMARY KEY, institute_id BIGINT NOT NULL REFERENCES institutes(id), session_id BIGINT NOT NULL REFERENCES attendance_sessions(id), student_id BIGINT NOT NULL REFERENCES students(id), status VARCHAR(20) NOT NULL CHECK(status IN ('PRESENT','ABSENT','LATE','EXCUSED')), marked_by BIGINT NOT NULL REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(session_id,student_id));
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, institute_id BIGINT NOT NULL REFERENCES institutes(id), actor_id BIGINT NOT NULL REFERENCES users(id), action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(80) NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_sessions_tenant_date ON attendance_sessions(institute_id,session_date);
CREATE INDEX idx_records_tenant_session ON attendance_records(institute_id,session_id);
CREATE INDEX idx_audit_tenant_time ON audit_events(institute_id,created_at DESC);
